(()=>{
'use strict';
const $=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const words={
title:['ผลการเรียนรู้ของผู้เล่น','學習結果','Player learning results'],language:['ภาษา','語言','Language'],intro:['ดูคำตอบรายคน และเลือกชุดข้อมูลสำหรับสรุปผล','查看個人答案及篩選統計資料','Review individual replies and select runs for analysis.'],refresh:['โหลดข้อมูลล่าสุด','重新載入','Refresh data'],search:['ชื่อ / รหัส / บัญชี','姓名／學號／帳號','Name / ID / account'],group:['กลุ่มเรียน','班級','Class / group'],attempt:['รอบที่นำมาสรุป','統計回合','Attempt policy'],latest:['รอบล่าสุดที่จบ / คน','每人最近完成回合','Latest completed per person'],first:['รอบแรกที่จบ / คน','每人首次完成回合','First completed per person'],allRuns:['ทุกรอบ','所有回合','All runs'],all:['ทั้งหมด','全部','All'],from:['ตั้งแต่วันที่','起始日期','From date'],to:['ถึงวันที่','截止日期','To date'],runStatus:['สถานะ','狀態','Status'],completed:['จบรอบ','已完成','Completed'],incomplete:['ยังไม่จบ','未完成','Incomplete'],playLanguage:['ภาษาที่เล่น','遊玩語言','Play language'],pace:['เวลาต่อคำถามในเคส','個案作答時限','Case reply budget'],version:['เวอร์ชันเกม','遊戲版本','Game version'],reset:['ล้างตัวกรอง','清除篩選','Reset filters'],questions:['แนวโน้มรายคำถาม','各題趨勢','Question trends'],questionHint:['เรียงจากอัตราตอบถูกน้อยสุด · คลิกดูการกระจายคำตอบ','依正確率由低到高排序 · 點擊查看答案分布','Lowest correct rate first · expand to see replies'],runs:['ผลรายคนและรายรอบ','個人與回合結果','Players and runs'],exportSummary:['CSV สรุปคะแนน','成績摘要 CSV','Scores CSV'],exportAnswers:['CSV คำตอบ','答案 CSV','Replies CSV'],exportNote:['ส่งออกเฉพาะข้อมูลที่ผ่านตัวกรองข้างต้น','僅匯出符合以上篩選的資料','Exports include only the selected runs.'],player:['ผู้เล่น','學習者','Player'],started:['เริ่มเล่น','開始時間','Started'],knowledge:['ความรู้','知識','Knowledge'],safety:['ความปลอดภัย','安全','Safety'],answers:['คำตอบ','答案','Replies'],details:['รายละเอียดคำตอบ','答案詳情','Reply details'],close:['ปิด','關閉','Close'],limits:['คะแนนเป็นกลไกเกมเพื่อประเมินการเรียนรู้เบื้องต้น ชื่อ/รหัสกรอกโดยผู้เล่น ผลยังไม่ผ่านการรับรองสำหรับสอบตัดสิน และระบบไม่ป้องกันการแก้ข้อมูลจากฝั่งผู้เล่น','分數用於初步學習評估。姓名及學號由玩家填寫，尚未驗證為正式考試工具，也不防止玩家端資料修改。','Game scores support formative review. Names and student IDs are self-reported. This is not a validated examination tool and does not prevent client-side score modification.'],loading:['กำลังโหลดข้อมูลทั้งหมด…','正在載入全部資料…','Loading all records…'],error:['โหลดไม่ได้ ลองใหม่ได้ · ไม่มีการแสดงข้อมูลที่โหลดมาไม่ครบ','載入失敗，請重試；不顯示不完整的資料。','Could not load. Retry; partial data is not shown.'],denied:['เฉพาะบัญชีอาจารย์เจ้าของเกมเท่านั้น','僅限遊戲教師帳號','Instructor account only.'],signIn:['ลงชื่อเข้าใช้','登入','Sign in'],empty:['ยังไม่มีข้อมูลที่เข้าเกณฑ์','沒有符合條件的紀錄','No matching records.'],players:['จำนวนผู้เล่น','學習者人數','Players'],selected:['รอบที่นำมาสรุป','選取回合','Selected runs'],meanKnowledge:['ความรู้เฉลี่ย · รอบที่จบ','平均知識 · 已完成','Mean knowledge · completed'],meanSafety:['ความปลอดภัยเฉลี่ย · รอบที่จบ','平均安全 · 已完成','Mean safety · completed'],meanSeconds:['เวลาเฉลี่ยต่อคำตอบ','平均作答時間','Mean reply time'],timeouts:['หมดเวลา','逾時','Timeouts'],correct:['ตอบถูก','答對','Correct'],count:['คำตอบที่บันทึก','已記錄答案','Recorded replies'],view:['ดูคำตอบ','查看答案','View replies'],chosen:['คำตอบที่เลือก','所選答案','Chosen reply'],correctAnswer:['คำตอบที่ถูก','正確答案','Correct answer'],feedback:['คำอธิบาย','說明','Feedback'],basis:['ตัวเลขอิงรอบที่ผ่านตัวกรอง · ค่าเฉลี่ยคะแนนคิดเฉพาะรอบที่จบ · อัตราตอบถูกคิดจากคำตอบที่มีบันทึก (คำตอบหมดเวลานับว่าผิด) · วันที่ใช้เวลาไทเป UTC+8','統計依篩選回合；分數平均僅計已完成回合，正確率以記錄的答案為分母（逾時算錯）；日期使用臺北 UTC+8。','Statistics use the selected runs. Score means use completed runs only. Correct rates use recorded replies (timeouts count as incorrect). Dates use Taipei UTC+8.'],repeated:['โหมดทุกรอบ: คนที่เล่นซ้ำมีน้ำหนักมากขึ้น','所有回合模式：重複遊玩的學習者權重較高。','All-runs mode gives repeat players more weight.'],academic:['คำถามความรู้','知識題','Knowledge question'],clinical:['บทสนทนาในเคส','個案對話','Case dialogue'],noGroup:['ไม่ระบุกลุ่ม','未填班級','No group'],loaded:['โหลดแล้ว','已載入','Loaded'],invalidDates:['วันเริ่มต้องไม่เกินวันสิ้นสุด','開始日期不得晚於截止日期','From date must not be after to date.'],answered:['ตอบแล้ว','已作答','Answered'],percentNote:['คะแนนเต็ม 12 · ไม่นับรอบที่ยังไม่จบ','滿分 12 · 不含未完成回合','Out of 12 · incomplete runs excluded']
};
let lang='th',all=[],filtered=[],busy=false,loaded=false;const ui=k=>words[k]?.[['th','zh','en'].indexOf(lang)]||k,num=(x,d=1)=>x===null||x===undefined?'—':Number(x).toFixed(d);
const date=x=>new Intl.DateTimeFormat(lang==='zh'?'zh-TW':lang,{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Taipei'}).format(new Date(x));
function download(payload,name,type){const url=URL.createObjectURL(new Blob([payload],{type})),a=document.createElement('a');a.href=url;a.download='Heart-of-Care-'+name+'-'+new Date().toISOString().slice(0,10);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^\s*[=+@-]/.test(s)&&!/^[-+]?\d+(\.\d+)?$/.test(s.trim()))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function filterValues(id,values){const old=$(id).value;$(id).innerHTML=`<option value="">${ui('all')}</option>`+[...new Set(values.filter(Boolean))].sort().map(v=>`<option value="${escape(v)}">${escape(v)}</option>`).join('');$(id).value=[...$(id).options].some(o=>o.value===old)?old:'';}
function translate(){document.documentElement.lang=lang==='zh'?'zh-Hant':lang;document.querySelectorAll('[data-label]').forEach(el=>el.textContent=ui(el.dataset.label));filterValues('group',all.map(s=>s.group));filterValues('version',all.map(s=>s.gameVersion));render();}
function filters(){return {search:$('search').value.trim(),group:$('group').value,attempt:$('attempt').value,from:$('from').value,to:$('to').value,status:$('run-status').value,language:$('play-language').value,pace:$('pace').value,version:$('version').value};}
function render(){
 const f=filters(),invalid=f.from&&f.to&&f.from>f.to;filtered=invalid?[]:CARE_ANALYTICS.select(all,f);const s=CARE_ANALYTICS.summarize(filtered);
 $('basis').textContent=ui('basis')+(f.attempt==='all'?' '+ui('repeated'):'');
 $('stats').innerHTML=[[s.players,'players'],[s.runs,'selected'],[num(s.meanKnowledge)+'%','meanKnowledge'],[num(s.meanSafety)+'/100','meanSafety'],[s.completed,'completed'],[s.incomplete,'incomplete'],[num(s.meanSeconds)+'s','meanSeconds'],[s.timeouts+'/'+s.answers,'timeouts']].map(([v,k])=>`<div class="stat"><strong>${escape(v)}</strong><span>${ui(k)}</span></div>`).join('');
 $('questions').innerHTML=s.questions.length?s.questions.map(q=>`<details class="question"><summary><div><span class="badge">${ui(q.academic?'academic':'clinical')}</span> ${escape(q.id)}<p>${escape(q.prompt)}</p><small>${q.count} ${ui('count')} · ${num(q.meanSeconds)}s · ${ui('timeouts')} ${q.timeouts}</small><span class="bar"><span style="width:${q.rate}%"></span></span></div><strong>${ui('correct')} ${num(q.rate)}%</strong></summary>${q.options.map(o=>`<div class="option"><span class="badge ${o.correctness===2?'':'review'}">${o.count}/${q.count} · ${num(100*o.count/q.count)}%</span> ${escape(o.timeout?ui('timeouts'):o.label)} <small>${escape(o.language)}</small></div>`).join('')}</details>`).join(''):`<p>${ui('empty')}</p>`;
 $('run-rows').innerHTML=filtered.map((r,i)=>{const k=r.result?.knowledge||r.knowledge;return `<tr><td>${escape(r.name)}<small>${escape(r.studentCode||'')} · ${escape(r.accountEmail||'')}</small></td><td>${escape(r.group||ui('noGroup'))}</td><td>${escape(date(r.startedAt))}<small>${escape(r.language)} · ${r.pace}s · v${escape(r.gameVersion)}</small></td><td>${ui(r.status==='completed'?'completed':'incomplete')}</td><td>${k.correct}/${k.total}<small>${ui('answered')} ${k.answered}</small></td><td>${r.result?num(r.result.safety,0):'—'}</td><td>${r.answers.length}</td><td><button data-run-index="${i}">${ui('view')}</button></td></tr>`;}).join('')||`<tr><td colspan="8">${ui('empty')}</td></tr>`;
 ['export-summary','export-answers','export-json'].forEach(id=>$(id).disabled=busy||!loaded||!filtered.length);if(invalid)$('status').textContent=ui('invalidDates');else if(loaded&&!busy)$('status').textContent=ui('loaded')+' · '+all.length+' '+ui('allRuns');
}
async function load(){busy=true;loaded=false;all=[];$('refresh').disabled=true;$('status').textContent=ui('loading');render();try{let cursor=null,rows=[];do{const r=await fetch('/api/admin/sessions'+(cursor?'?cursor='+encodeURIComponent(cursor):''),{cache:'no-store'});if(!r.ok){const e=new Error();e.status=r.status;throw e;}const data=await r.json();rows.push(...data.sessions);cursor=data.nextCursor;}while(cursor);all=rows;loaded=true;filterValues('group',all.map(s=>s.group));filterValues('version',all.map(s=>s.gameVersion));}catch(e){$('status').textContent=e.status===403||e.status===401?ui('denied'):ui('error');if(e.status===401){if(window.parent!==window)window.parent.postMessage({type:'care-admin-auth-required'},location.origin);else{const a=document.createElement('a');a.href='/#admin';a.textContent=' '+ui('details');$('status').append(a);}}}finally{busy=false;$('refresh').disabled=false;render();}}
function details(index){const s=filtered[index];if(!s)return;$('run-detail').innerHTML=`<h3>${escape(s.name)}</h3><p>${escape(s.studentCode||'')} · ${escape(s.group||'')}<br>${escape(s.accountEmail||'')}<br>${escape(date(s.startedAt))}</p>${s.answers.map((a,i)=>`<details class="answer"><summary>${i+1}. ${escape(a.nodeId)} · ${a.timeout?ui('timeouts'):a.correctness===2?ui('correct'):'○'} · ${num(a.elapsedSeconds)}s</summary><p>${escape(a.prompt)}</p><p><strong>${ui('chosen')}:</strong> ${escape(a.choice)}</p><p><strong>${ui('correctAnswer')}:</strong> ${escape(a.correctAnswer)}</p><p><strong>${ui('feedback')}:</strong> ${escape(a.reaction)} ${escape(a.explanation)}</p><p>${escape(a.lesson)}</p><p class="note">${escape(date(a.answeredAt))} · ${num(a.elapsedSeconds)}/${a.budget}s · ${escape(a.emotion)} · ${ui('safety')} ${a.safetyAfter}/100</p>${a.sources.map(x=>`<a href="${escape(x.url)}" target="_blank" rel="noopener noreferrer">${escape(x.title)}</a>`).join('<br>')}</details>`).join('')}`;$('run-dialog').showModal();}
 $('admin-language').addEventListener('change',()=>{lang=$('admin-language').value;translate();});$('refresh').addEventListener('click',load);$('close').addEventListener('click',()=>$('run-dialog').close());
 document.querySelector('.filters').addEventListener('input',render);document.querySelector('.filters').addEventListener('change',render);$('reset').addEventListener('click',()=>{document.querySelectorAll('.filters input').forEach(e=>e.value='');document.querySelectorAll('.filters select').forEach(e=>e.value=e.id==='attempt'?'latest':'');render();});
 $('run-rows').addEventListener('click',e=>{const b=e.target.closest('[data-run-index]');if(b)details(+b.dataset.runIndex);});
 $('export-json').addEventListener('click',()=>download(JSON.stringify({exportedAt:new Date().toISOString(),filters:filters(),statistics:CARE_ANALYTICS.summarize(filtered),sessions:filtered},null,2),'assessment.json','application/json;charset=utf-8'));
 $('export-summary').addEventListener('click',()=>download(csv([['account_id','account_email','student_code','name','group','session_id','started_at','status','game_version','language','pace_seconds','knowledge_correct','knowledge_total','academic_answered','safety','reply_count','timeout_count','mean_reply_seconds'],...filtered.map(s=>{const k=s.result?.knowledge||s.knowledge;return [s.accountId,s.accountEmail,s.studentCode,s.name,s.group,s.id,s.startedAt,s.status,s.gameVersion,s.language,s.pace,k.correct,k.total,k.answered,s.result?.safety??'',s.answers.length,s.answers.filter(a=>a.timeout).length,num(CARE_ANALYTICS.summarize([s]).meanSeconds)];})]),'scores.csv','text/csv;charset=utf-8'));
 $('export-answers').addEventListener('click',()=>download(CARE_HISTORY.csv(filtered,true),'replies.csv','text/csv;charset=utf-8'));
 translate();load();
})();
